function showInput(){inputOpen=true;$('#composer').hidden=false;document.body.classList.add('input-screen');$('#composer').classList.add('input-open');$('#open-input').setAttribute('aria-expanded','true');}
let inputOriginScroll=0;
function openInput(){
 if(!inputOpen){inputOriginScroll=window.scrollY;if(location.hash!=='#'+tab)history.replaceState(null,'','#'+tab);history.pushState({inputOrigin:tab},'','#input');showInput();}
 $('#input').focus();
}
function dismissInput(goBack=true){
 if(!inputOpen)return;
 inputOpen=false;stopVoice();document.body.classList.remove('input-screen');$('#composer').classList.remove('input-open');$('#open-input').setAttribute('aria-expanded','false');$('#input').blur();render();requestAnimationFrame(()=>window.scrollTo(0,inputOriginScroll));
 if(goBack&&location.hash==='#input'){if(history.state?.inputOrigin)history.back();else history.replaceState(null,'','#'+tab);}
}
$('#close-input').onclick=()=>dismissInput();$('#cancel-input').onclick=()=>$('#close-input').onclick();$('#quick-add').onclick=openInput;$('#open-input').onclick=openInput;$('#manual').onclick=manual;$('#organize').onclick=()=>runOrganize();$('#cancel-ai').onclick=()=>controller?.abort();
$('#input').oninput=()=>{try{localStorage.setItem('jinzhan-draft',$('#input').value);}catch{toast('草稿暂存失败，请不要关闭页面');}};

// 浏览器语音识别：识别文字直接进入输入框，可修改后再整理；不经过任何第三方页面。
const SRClass=window.SpeechRecognition||window.webkitSpeechRecognition;
let recog=null,listening=false,voiceBase='',skipDupFinal=false;
function voiceState(){const b=$('#voice');if(!b)return;b.classList.toggle('listening',listening);b.setAttribute('aria-pressed',String(listening));b.textContent=listening?'● 正在听，点一下停止':'🎙 语音输入';}
function stopVoice(){listening=false;try{recog?.stop();}catch{}voiceState();}
function startVoice(){if(listening)return stopVoice();if(!SRClass)return toast('当前浏览器不支持网页语音识别；可直接打字或用输入法语音');openInput();voiceBase=$('#input').value;try{recog??=new SRClass();}catch(e){return toast('无法启动语音识别：'+e.message);}
 recog.lang='zh-CN';recog.continuous=true;recog.interimResults=true;recog.maxAlternatives=1;
 recog.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const r=e.results[i];if(r.isFinal){const t=r[0].transcript;if(!(skipDupFinal&&i===e.resultIndex&&voiceBase.endsWith(t)))voiceBase+=t;skipDupFinal=false;}else interim+=r[0].transcript;}$('#input').value=voiceBase+interim;$('#input').dispatchEvent(new Event('input',{bubbles:true}));};
 recog.onerror=e=>{if(e.error==='no-speech'||e.error==='aborted')return;if(e.error==='not-allowed'||e.error==='service-not-allowed'){toast('麦克风权限被拒绝；可在浏览器地址栏的权限设置里允许后重试');stopVoice();}else if(e.error==='network'){toast('语音识别服务暂时不可用（需要网络）；文字输入不受影响');stopVoice();}else{stopVoice();toast('语音识别已停止（'+e.error+'）；可直接打字，或再点一次麦克风重试');}};
 recog.onend=()=>{if(listening){skipDupFinal=true;try{recog.start();}catch{listening=false;voiceState();}}else voiceState();};
 listening=true;voiceState();try{recog.start();toast('正在聆听……说完点一下麦克风停止，文字可直接修改');}catch(e){listening=false;voiceState();toast('语音识别启动失败，请再试一次');}
}
$('#voice').onclick=startVoice;
if(!SRClass)$('#voice').hidden=true;
window.addEventListener('pagehide',()=>{if(listening)stopVoice();});
