$('#today').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date());
try{state=await readState();$('#input').value=localStorage.getItem('jinzhan-draft')||'';if($('#input').value)$('#open-input').firstChild.textContent='继续上次的草稿……';tab=labels[location.hash.slice(1)]?location.hash.slice(1):(location.hash==='#input'&&labels[history.state?.inputOrigin]?history.state.inputOrigin:'now');render();if(location.hash==='#input')showInput();}catch(e){$('#content').innerHTML=`<div class="notice error">${esc(e.message)}。请换用允许本地存储的普通浏览窗口。</div>`;$('#organize').disabled=true;$('#manual').disabled=true;}
