if(document.modelContext?.registerTool){const lifetime=new AbortController();const tools=[{name:'read_jinzhan_actions',description:'Read the current saved actions and their progress. Does not change data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{state=await readState();return {tasks:state.tasks};}},{name:'append_jinzhan_progress',description:'Save an explicit progress note to an existing action, preserving its date and history.',inputSchema:{type:'object',properties:{taskId:{type:'string'},content:{type:'string'},nextStep:{type:'string'}},required:['taskId','content'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async x=>{if(typeof x?.taskId!=='string'||typeof x?.content!=='string'||!x.content.trim())throw Error('需要有效行动编号和进展');const id=uid();await save(s=>appendUpdate(s,x.taskId,{id,content:x.content,nextStep:typeof x.nextStep==='string'?x.nextStep:null}));return {saved:true,updateId:id};}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}

// Match the visible phone viewport while browser chrome or the keyboard changes height.
function syncPhoneViewport(){
 const v=window.visualViewport;
 const height=v?.height||window.innerHeight;
 document.documentElement.style.setProperty('--visual-height',height+'px');
 document.documentElement.style.setProperty('--visual-top',(v?.offsetTop||0)+'px');
 const editing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'');
 document.body.classList.toggle('keyboard-open',editing&&(window.innerHeight-height>140||(matchMedia('(pointer:coarse)').matches&&height<screen.height*0.65)));
}
window.visualViewport?.addEventListener('resize',syncPhoneViewport);
window.visualViewport?.addEventListener('scroll',syncPhoneViewport);
window.addEventListener('resize',syncPhoneViewport);
document.addEventListener('focusin',syncPhoneViewport);
document.addEventListener('focusout',()=>requestAnimationFrame(syncPhoneViewport));
syncPhoneViewport();
